1	#!/usr/bin/env python3
2	"""OpenSurvey HTTP service."""
3	import argparse
4	import json
5	import re
6	from http.server import BaseHTTPRequestHandler, HTTPServer
7	from pathlib import Path
8	import signal
9	import sqlite3
10	from urllib.parse import urlsplit
11	
12	PRODUCT = "OpenSurvey"
13	RESOURCE = "surveys"
14	MAX_BODY_BYTES = 10 * 1024 * 1024
15	QUESTION_TYPES = ("text", "single_choice")
16	
17	PAGE = r"""<!doctype html>
18	<html lang="zh-CN">
19	<meta charset="utf-8">
20	<meta name="viewport" content="width=device-width,initial-scale=1">
21	<title>OpenSurvey · 问卷调查与反馈管理</title>
22	<style>
23	:root{--blue:#175b9c;--red:#c0392b;--grey:#666;--line:#d8dce3}
24	*{box-sizing:border-box}
25	body{font-family:system-ui,"PingFang SC","Microsoft YaHei",sans-serif;max-width:52rem;margin:2.5rem auto;padding:0 1rem;line-height:1.7;color:#1f2430}
26	a{color:var(--blue)}
27	h1{margin-bottom:.2rem}
28	h2{margin-top:2.2rem;border-bottom:1px solid var(--line);padding-bottom:.3rem}
29	.muted{color:var(--grey);font-size:.92rem}
30	ul.plain{list-style:none;padding-left:0}
31	ul.plain li{padding:.25rem 0;border-bottom:1px dashed var(--line)}
32	form label{display:block;margin:1rem 0 .25rem;font-weight:600}
33	input[type=text],textarea,input.opt-text,input.q-title{width:100%;padding:.5rem .6rem;border:1px solid var(--line);border-radius:.35rem;font:inherit}
34	textarea{resize:vertical}
35	.card{border:1px solid var(--line);border-radius:.5rem;padding:1rem 1.2rem;margin:1rem 0;background:#fafbfd}
36	.q-head{display:flex;align-items:center;gap:.7rem;flex-wrap:wrap;margin-bottom:.5rem}
37	.q-index{font-weight:700}
38	.tag{font-size:.8rem;background:#e8f0fa;color:var(--blue);border-radius:1rem;padding:.05rem .6rem}
39	.tag.required{background:#fdecea;color:var(--red)}
40	.req{margin:0;font-weight:400;display:flex;align-items:center;gap:.3rem}
41	.spacer{flex:1}
42	button{font:inherit;cursor:pointer}
43	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
44	.btn.secondary{background:#fff;color:var(--blue)}
45	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
46	.link.danger{color:var(--red)}
47	.row-actions{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.2rem}
48	.opt-row{display:flex;align-items:center;gap:.6rem;margin:.4rem 0}
49	.opt-index{color:var(--grey);font-size:.9rem;min-width:3.2rem}
50	.banner{border:1px solid var(--red);background:#fdf3f2;color:var(--red);border-radius:.5rem;padding:.7rem 1rem;margin:1rem 0;white-space:normal}
51	.banner ul{margin:.4rem 0 0;padding-left:1.2rem}
52	.banner button{color:var(--red);text-decoration:underline;background:none;border:none;padding:0;text-align:left}
53	.field-err{color:var(--red);font-size:.85rem;margin:.25rem 0 0;min-height:1px}
54	.invalid{border-color:var(--red)!important;background:#fdf6f5}
55	.detail-meta{color:var(--grey);font-size:.9rem}
56	.detail-desc,.opt-text-display{white-space:pre-wrap}
57	.q-list>li{margin:1rem 0}
58	.q-list .q-line{font-weight:600}
59	.q-list ol{margin:.4rem 0 0 1.4rem}
60	</style>
61	<main>
62	<h1>OpenSurvey</h1>
63	<p>问卷调查与反馈管理</p>
64	<div id="app"></div>
65	<p class="muted"><a href="/api/surveys">问卷列表接口</a> · <a href="/health">服务状态</a></p>
66	</main>
67	<script>
68	"use strict";
69	const app = document.getElementById("app");
70	
71	// 每次进入一个页面都开启新一代视图：切换首页/详情/编辑、重新进入同一份问卷、
72	// 重试加载以及浏览器前进/后退都会使代数递增。较早一代页面发起的请求再晚
73	// 返回也必须丢弃，不能覆盖用户当前所在页面。
74	let activeView = 0;
75	
76	function h(tag, attrs, ...children) {
77	  const el = document.createElement(tag);
78	  if (attrs) for (const [k, v] of Object.entries(attrs)) {
79	    if (v === null || v === undefined) continue;
80	    if (k === "class") el.className = v;
81	    else if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
82	    else el.setAttribute(k, v);
83	  }
84	  for (const child of children.flat()) {
85	    if (child === null || child === undefined) continue;
86	    el.append(child.nodeType ? child : document.createTextNode(String(child)));
87	  }
88	  return el;
89	}
90	
91	/* ---------- 问卷表单（新建 / 编辑共用） ---------- */
92	
93	function buildSurveyForm(existing, hooks, view) {
94	  const mode = existing ? "edit" : "create";
95	
96	  const banner = h("div", {class: "banner", id: "form-banner"});
97	  banner.hidden = true;
98	
99	  const titleInput = h("input", {type: "text", id: "survey-title", maxlength: "200", placeholder: "请输入问卷标题"});
100	  const titleErr = h("p", {class: "field-err", id: "title-err"});
101	  const descArea = h("textarea", {id: "survey-desc", rows: "4", placeholder: "问卷说明（可留空，支持中文、引号与换行）"});
102	  const qBox = h("div", {id: "questions"});
103	  const qErr = h("p", {class: "field-err", id: "questions-err"});
104	
105	  function renumber() {
106	    const cards = qBox.querySelectorAll(".q-card");
107	    cards.forEach((card, i) => {
108	      card.querySelector(".q-index").textContent = `第 ${i + 1} 题`;
109	      card.querySelectorAll(".opt-row").forEach((row, j) => {
110	        row.querySelector(".opt-index").textContent = `选项 ${j + 1}`;
111	      });
112	    });
113	  }
114	
115	  function optionRow(value) {
116	    const text = h("input", {type: "text", class: "opt-text", placeholder: "选项内容"});
117	    if (value !== undefined && value !== null) text.value = value;
118	    const row = h("div", {class: "opt-row"},
119	      h("span", {class: "opt-index"}, "选项"),
120	      text,
121	      h("button", {type: "button", class: "link danger", onclick: () => { row.remove(); renumber(); }}, "删除")
122	    );
123	    return row;
124	  }
125	
126	  function addQuestion(type, prefill) {
127	    const isChoice = type === "single_choice";
128	    const options = h("div", {class: "options"});
129	    const card = h("div", {class: "card q-card", "data-type": type},
130	      h("div", {class: "q-head"},
131	        h("span", {class: "q-index"}, "第 N 题"),
132	        h("span", {class: "tag q-type-tag"}, isChoice ? "单选题" : "文本题"),
133	        h("label", {class: "req"},
134	          h("input", {type: "checkbox", class: "q-required"}), "必填（默认非必填）"),
135	        h("span", {class: "spacer"}),
136	        h("button", {type: "button", class: "link danger", onclick: () => { card.remove(); renumber(); }}, "删除本题")
137	      ),
138	      h("input", {type: "text", class: "q-title", placeholder: "题目标题"}),
139	      h("p", {class: "field-err q-title-err"})
140	    );
141	    if (isChoice) {
142	      const saved = prefill && Array.isArray(prefill.options) ? prefill.options : null;
143	      if (saved && saved.length) saved.forEach(value => options.append(optionRow(value)));
144	      else options.append(optionRow(), optionRow());
145	      card.append(
146	        options,
147	        h("p", {class: "field-err opt-err"}),
148	        h("button", {type: "button", class: "link add-opt"}, "添加选项")
149	      );
150	      card.querySelector(".add-opt").addEventListener("click", () => {
151	        options.append(optionRow());
152	        renumber();
153	        options.querySelector(".opt-row:last-child .opt-text").focus();
154	      });
155	    }
156	    if (prefill) {
157	      card.querySelector(".q-title").value = prefill.title != null ? prefill.title : "";
158	      card.querySelector(".q-required").checked = !!prefill.required;
159	    }
160	    qBox.append(card);
161	    renumber();
162	    if (!prefill) card.querySelector(".q-title").focus();
163	    return card;
164	  }
165	
166	  function clearErrors() {
167	    banner.hidden = true;
168	    banner.replaceChildren();
169	    titleErr.textContent = "";
170	    qErr.textContent = "";
171	    qBox.querySelectorAll(".invalid").forEach(el => el.classList.remove("invalid"));
172	    qBox.querySelectorAll(".field-err").forEach(el => { el.textContent = ""; });
173	  }
174	
175	  function showBanner(items) {
176	    banner.replaceChildren(h("strong", null, "问卷未能保存，请修改后重试："), h("ul", null,
177	      items.map(it => h("li", null, h("button", {type: "button", onclick: () => it.el && it.el.focus()}, it.msg)))));
178	    banner.hidden = false;
179	    banner.scrollIntoView({behavior: "smooth", block: "nearest"});
180	  }
181	
182	  const actionButtons = [
183	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("text")}, "添加文本题"),
184	    h("button", {type: "button", class: "btn secondary", onclick: () => addQuestion("single_choice")}, "添加单选题"),
185	    h("span", {class: "spacer"})
186	  ];
187	  if (mode === "edit") {
188	    // 离开编辑页即丢弃全部未保存的增删与输入
189	    actionButtons.push(h("a", {class: "btn secondary", href: `#/surveys/${existing.id}`}, "取消"));
190	  }
191	  actionButtons.push(h("button", {type: "submit", class: "btn"},
192	    mode === "edit" ? "保存修改" : "保存整份问卷"));
193	
194	  const form = h("form", {id: "draft-form", onsubmit: submitForm},
195	    banner,
196	    h("section", null,
197	      h("h2", null, mode === "edit" ? `编辑问卷草稿 #${existing.id}` : "新建问卷草稿"),
198	      mode === "edit"
199	        ? h("p", {class: "muted"}, "保存将整份替换当前草稿；取消则放弃本次修改，问卷编号和地址不变。")
200	        : null,
201	      h("label", {for: "survey-title"}, "标题"),
202	      titleInput, titleErr,
203	      h("label", {for: "survey-desc"}, "说明"),
204	      descArea,
205	      h("label", null, "题目（按下方顺序保存，至少保留一道题）"),
206	      qBox, qErr,
207	      h("div", {class: "row-actions"}, actionButtons)
208	    )
209	  );
210	
211	  if (mode === "edit") {
212	    titleInput.value = existing.title != null ? existing.title : "";
213	    descArea.value = existing.description || "";
214	    existing.questions.forEach(question => addQuestion(question.type, question));
215	    renumber();
216	  }
217	
218	  async function submitForm(event) {
219	    event.preventDefault();
220	    clearErrors();
221	    const problems = [];
222	
223	    const title = titleInput.value.trim();
224	    if (!title) {
225	      titleInput.classList.add("invalid");
226	      titleErr.textContent = "标题不能为空。";
227	      problems.push({el: titleInput, msg: "问卷标题不能为空。"});
228	    }
229	
230	    const cards = [...qBox.querySelectorAll(".q-card")];
231	    if (cards.length === 0) {
232	      qErr.textContent = "问卷至少需要保留一道题。";
233	      problems.push({el: qBox, msg: "问卷至少需要保留一道题，请先添加题目。"});
234	    }
235	
236	    const payloadQuestions = [];
237	    cards.forEach((card, i) => {
238	      const loc = `第 ${i + 1} 题`;
239	      const titleEl = card.querySelector(".q-title");
240	      const qTitle = titleEl.value.trim();
241	      if (!qTitle) {
242	        titleEl.classList.add("invalid");
243	        card.querySelector(".q-title-err").textContent = `${loc}：题目标题不能为空。`;
244	        problems.push({el: titleEl, msg: `${loc}：题目标题不能为空。`});
245	      }
246	      const q = {
247	        type: card.dataset.type,
248	        title: qTitle,
249	        required: card.querySelector(".q-required").checked
250	      };
251	      if (card.dataset.type === "single_choice") {
252	        const optInputs = [...card.querySelectorAll(".opt-text")];
253	        const values = optInputs.map(el => el.value.trim());
254	        const optErr = card.querySelector(".opt-err");
255	        const seen = new Set();
256	        values.forEach((val, j) => {
257	          if (!val) {
258	            optInputs[j].classList.add("invalid");
259	            optErr.textContent = `${loc}：第 ${j + 1} 个选项不能为空。`;
260	            problems.push({el: optInputs[j], msg: `${loc}：第 ${j + 1} 个选项不能为空。`});
261	          } else if (seen.has(val)) {
262	            optInputs[j].classList.add("invalid");
263	            optErr.textContent = `${loc}：选项“${val}”与同题其他选项重复。`;
264	            problems.push({el: optInputs[j], msg: `${loc}：选项“${val}”重复。`});
265	          }
266	          seen.add(val);
267	        });
268	        if (values.length < 2) {
269	          optErr.textContent = `${loc}：单选题至少需要两个选项。`;
270	          problems.push({el: card.querySelector(".add-opt"), msg: `${loc}：单选题至少需要两个选项。`});
271	        }
272	        q.options = values;
273	      }
274	      payloadQuestions.push(q);
275	    });
276	
277	    if (problems.length) {
278	      showBanner(problems);
279	      return;
280	    }
281	
282	    const payload = {title, description: descArea.value, questions: payloadQuestions};
283	    const endpoint = mode === "edit" ? `/api/surveys/${existing.id}` : "/api/surveys";
284	    // 这次保存只属于发起它的那一代表单；响应再晚返回，只要用户已经离开
285	    // （首页/详情/编辑切换、重新进入同一问卷、浏览器前进后退），其成功或
286	    // 失败结果都必须静默丢弃，不能跳转、清空或提示到当前页面上。
287	    const submitView = view;
288	    let resp;
289	    try {
290	      resp = await fetch(endpoint, {
291	        method: mode === "edit" ? "PUT" : "POST",
292	        headers: {"Content-Type": "application/json"},
293	        body: JSON.stringify(payload)
294	      });
295	    } catch (err) {
296	      if (submitView !== activeView) return;
297	      // 请求未成功：保留当前全部输入与增删结果
298	      showBanner([{el: null, msg: `网络错误，问卷尚未保存：${err}`}]);
299	      return;
300	    }
301	    if (submitView !== activeView) return;
302	    let data = {};
303	    try { data = await resp.json(); } catch (_) { /* 保留已输入内容 */ }
304	    if (submitView !== activeView) return;
305	    const saved = mode === "edit" ? resp.status === 200 : resp.status === 201;
306	    if (saved && data.id !== undefined) {
307	      if (mode === "create") {
308	        form.reset();
309	        qBox.replaceChildren();
310	        if (hooks && hooks.onCreated) hooks.onCreated();
311	      }
312	      location.hash = `#/surveys/${data.id}`;
313	      return;
314	    }
315	    // 服务端未确认保存成功：不清空任何输入，展示具体问题
316	    showBanner([{el: null, msg: data.error || `保存失败（HTTP ${resp.status}），问卷未保存，请检查后重试。`}]);
317	  }
318	
319	  return form;
320	}
321	
322	/* ---------- 首页 ---------- */
323	
324	function renderHome() {
325	  const view = ++activeView;
326	  app.replaceChildren();
327	
328	  const listSection = h("section", null,
329	    h("h2", null, "问卷列表"),
330	    h("ul", {class: "plain", id: "survey-list"}, h("li", {class: "muted"}, "加载中…"))
331	  );
332	  const listEl = listSection.querySelector("#survey-list");
333	
334	  async function loadSurveys() {
335	    let data;
336	    try {
337	      const resp = await fetch("/api/surveys");
338	      data = await resp.json();
339	    } catch (err) {
340	      if (view !== activeView) return;
341	      listEl.replaceChildren(h("li", {class: "muted"}, "问卷列表加载失败。"));
342	      return;
343	    }
344	    if (view !== activeView) return;
345	    listEl.replaceChildren();
346	    if (!data.surveys.length) {
347	      listEl.append(h("li", {class: "muted"}, "还没有问卷记录。"));
348	      return;
349	    }
350	    for (const survey of data.surveys) {
351	      listEl.append(h("li", null,
352	        h("a", {href: `#/surveys/${survey.id}`}, `#${survey.id} ${survey.title}`)));
353	    }
354	  }
355	
356	  app.append(
357	    listSection,
358	    buildSurveyForm(null, {onCreated: loadSurveys}, view)
359	  );
360	  loadSurveys();
361	}
362	
363	/* ---------- 问卷详情 ---------- */
364	
365	async function renderDetail(id) {
366	  const view = ++activeView;
367	  app.replaceChildren(
368	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
369	    h("p", {class: "muted", id: "detail-status"}, "加载中…")
370	  );
371	  const status = document.getElementById("detail-status");
372	
373	  let survey;
374	  try {
375	    const resp = await fetch(`/api/surveys/${id}`);
376	    if (view !== activeView) return;
377	    if (resp.status === 404) {
378	      status.textContent = `问卷 #${id} 不存在。`;
379	      return;
380	    }
381	    if (!resp.ok) {
382	      status.textContent = `详情加载失败（HTTP ${resp.status}），请稍后重试。`;
383	      return;
384	    }
385	    survey = await resp.json();
386	  } catch (err) {
387	    if (view !== activeView) return;
388	    status.textContent = `详情加载失败：${err}`;
389	    return;
390	  }
391	  if (view !== activeView) return;
392	
393	  app.replaceChildren(
394	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
395	    h("h2", null, `#${survey.id} ${survey.title}`),
396	    h("div", {class: "row-actions"},
397	      h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿"),
398	      h("a", {class: "btn secondary", href: "#/"}, "返回首页")
399	    ),
400	    h("h3", null, "说明"),
401	    survey.description
402	      ? h("p", {class: "detail-desc"}, survey.description)
403	      : h("p", {class: "muted"}, "（无说明）"),
404	    h("h3", null, `题目（共 ${survey.questions.length} 道）`)
405	  );
406	  if (!survey.questions.length) {
407	    app.append(
408	      h("p", {class: "muted"}, "该问卷草稿还没有题目，可进入编辑补齐。"),
409	      h("p", null, h("a", {class: "btn", href: `#/surveys/${survey.id}/edit`}, "编辑草稿并添加题目"))
410	    );
411	    return;
412	  }
413	  app.append(h("ol", {class: "q-list"},
414	    survey.questions.map((q, i) => h("li", null,
415	      h("div", {class: "q-line"},
416	        `${i + 1}. ${q.title} `,
417	        h("span", {class: "tag"}, q.type === "single_choice" ? "单选题" : "文本题"),
418	        " ",
419	        h("span", {class: "tag" + (q.required ? " required" : "")}, q.required ? "必填" : "选填")
420	      ),
421	      q.options && q.options.length
422	        ? h("ol", {start: "1"}, q.options.map(opt => h("li", {class: "opt-text-display"}, opt)))
423	        : null
424	    )))
425	  );
426	}
427	
428	/* ---------- 编辑草稿 ---------- */
429	
430	function showEditLoadError(id, message, view) {
431	  // 加载失败时明确提示，绝不能用空白编辑表单覆盖已有内容
432	  if (view !== activeView) return;
433	  app.replaceChildren(
434	    h("p", null, h("a", {href: "#/"}, "← 返回首页")),
435	    h("h2", null, `编辑问卷草稿 #${id}`),
436	    h("div", {class: "banner", role: "alert"},
437	      h("strong", null, "问卷内容加载失败，未打开编辑表单："),
438	      h("p", {class: "detail-meta", style: "margin:.4rem 0 0"}, message),
439	      h("p", {style: "margin:.6rem 0 0"},
440	        h("button", {type: "button", class: "btn secondary", onclick: () => renderEdit(id)}, "重试"), " ",
441	        h("a", {class: "btn secondary", href: `#/surveys/${id}`}, "返回详情"))
442	    )
443	  );
444	}
445	
446	async function renderEdit(id) {
447	  const view = ++activeView;
448	  app.replaceChildren(
449	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
450	    h("p", {class: "muted", id: "edit-status"}, "加载中…")
451	  );
452	
453	  let survey;
454	  try {
455	    const resp = await fetch(`/api/surveys/${id}`);
456	    if (view !== activeView) return;
457	    if (resp.status === 404) {
458	      showEditLoadError(id, `问卷 #${id} 不存在。`, view);
459	      return;
460	    }
461	    if (!resp.ok) {
462	      showEditLoadError(id, `服务端返回异常（HTTP ${resp.status}），请稍后重试。`, view);
463	      return;
464	    }
465	    survey = await resp.json();
466	  } catch (err) {
467	    showEditLoadError(id, `网络错误：${err}。已保存的问卷内容未受影响，可重试加载。`, view);
468	    return;
469	  }
470	
471	  if (view !== activeView) return;
472	  app.replaceChildren(
473	    h("p", null, h("a", {href: `#/surveys/${id}`}, "← 返回问卷详情")),
474	    buildSurveyForm(survey, {}, view)
475	  );
476	}
477	
478	function route() {
479	  const editMatch = location.hash.match(/^#\/surveys\/(\d+)\/edit$/);
480	  const detailMatch = location.hash.match(/^#\/surveys\/(\d+)$/);
481	  if (editMatch) renderEdit(Number(editMatch[1]));
482	  else if (detailMatch) renderDetail(Number(detailMatch[1]));
483	  else renderHome();
484	}
485	window.addEventListener("hashchange", route);
486	route();
487	</script>
488	</html>
489	"""
490	
491	
492	def validate_survey(obj):
493	    """Validate a decoded survey payload.
494	
495	    Returns (clean_survey, None) on success or (None, error_message) on failure.
496	    Strings are stored trimmed of surrounding whitespace; description keeps its
497	    raw value so Chinese, quotes and newlines are preserved.
498	    """
499	    if not isinstance(obj, dict):
500	        return None, "请求体必须是 JSON 对象"
501	    if "title" not in obj:
502	        return None, "缺少字段 title"
503	    title = obj["title"]
504	    if not isinstance(title, str):
505	        return None, "title 必须是字符串"
506	    title = title.strip()
507	    if not title:
508	        return None, "title 不能为空（或全为空白字符）"
509	
510	    description = obj.get("description", "")
511	    if not isinstance(description, str):
512	        return None, "description 必须是字符串"
513	
514	    if "questions" not in obj:
515	        return None, "缺少字段 questions"
516	    raw_questions = obj["questions"]
517	    if not isinstance(raw_questions, list):
518	        return None, "questions 必须是数组"
519	    if len(raw_questions) == 0:
520	        return None, "questions 至少需要一道题"
521	
522	    questions = []
523	    for index, raw_question in enumerate(raw_questions, start=1):
524	        location = f"第 {index} 题"
525	        if not isinstance(raw_question, dict):
526	            return None, f"{location}（questions[{index - 1}]）必须是对象"
527	
528	        if "type" not in raw_question:
529	            return None, f"{location}：缺少字段 type"
530	        question_type = raw_question["type"]
531	        if not isinstance(question_type, str):
532	            return None, f"{location}：type 必须是字符串"
533	        if question_type not in QUESTION_TYPES:
534	            shown = json.dumps(question_type, ensure_ascii=False)
535	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
536	
537	        if "title" not in raw_question:
538	            return None, f"{location}：缺少字段 title"
539	        question_title = raw_question["title"]
540	        if not isinstance(question_title, str):
541	            return None, f"{location}：title 必须是字符串"
542	        question_title = question_title.strip()
543	        if not question_title:
544	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
545	
546	        required = raw_question.get("required", False)
547	        if not isinstance(required, bool):
548	            return None, f"{location}：required 必须是布尔值"
549	
550	        raw_options = raw_question.get("options", [])
551	        if not isinstance(raw_options, list):
552	            return None, f"{location}：options 必须是数组"
553	
554	        options = []
555	        if question_type == "text":
556	            if len(raw_options) > 0:
557	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
558	        else:
559	            if len(raw_options) < 2:
560	                return None, f"{location}：单选题至少需要两个选项"
561	            seen = set()
562	            for option_index, raw_option in enumerate(raw_options, start=1):
563	                if not isinstance(raw_option, str):
564	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
565	                option = raw_option.strip()
566	                if not option:
567	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
568	                if option in seen:
569	                    shown = json.dumps(option, ensure_ascii=False)
570	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
571	                seen.add(option)
572	                options.append(option)
573	
574	        questions.append({
575	            "type": question_type,
576	            "title": question_title,
577	            "required": required,
578	            "options": options,
579	        })
580	
581	    return {
582	        "title": title,
583	        "description": description,
584	        "questions": questions,
585	    }, None
586	
587	
588	def main():
589	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
590	    commands = parser.add_subparsers(dest="command", required=True)
591	    serve = commands.add_parser("serve", help="Start the HTTP service")
592	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
593	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
594	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
595	    args = parser.parse_args()
596	    if not 0 <= args.port <= 65535:
597	        parser.error("port must be between 0 and 65535")
598	    args.data_dir.mkdir(parents=True, exist_ok=True)
599	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite")
600	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
601	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
602	    if "description" not in columns:
603	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
604	    database.execute(
605	        "CREATE TABLE IF NOT EXISTS questions ("
606	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
607	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
608	    )
609	    database.execute(
610	        "CREATE TABLE IF NOT EXISTS question_options ("
611	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
612	    )
613	    database.commit()
614	
615	    def survey_detail(survey_id):
616	        row = database.execute(
617	            "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
618	            (survey_id,),
619	        ).fetchone()
620	        if row is None:
621	            return None
622	        title, description = row
623	        questions = []
624	        question_rows = database.execute(
625	            "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
626	            (survey_id,),
627	        ).fetchall()
628	        for question_id, question_type, question_title, required in question_rows:
629	            options = [option_row[0] for option_row in database.execute(
630	                "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
631	                (question_id,),
632	            )]
633	            questions.append({
634	                "type": question_type,
635	                "title": question_title,
636	                "required": bool(required),
637	                "options": options,
638	            })
639	        return {
640	            "id": survey_id,
641	            "title": title,
642	            "description": description,
643	            "questions": questions,
644	        }
645	
646	    def save_survey(clean):
647	        """Insert the whole survey atomically; returns the new id."""
648	        try:
649	            cursor = database.execute(
650	                "INSERT INTO surveys (title, description) VALUES (?, ?)",
651	                (clean["title"], clean["description"]),
652	            )
653	            survey_id = cursor.lastrowid
654	            write_questions(survey_id, clean["questions"])
655	            database.commit()
656	            return survey_id
657	        except Exception:
658	            database.rollback()
659	            raise
660	
661	    def write_questions(survey_id, questions):
662	        """Replace all questions/options of a survey with the given ordered list."""
663	        old_question_ids = [row[0] for row in database.execute(
664	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
665	        )]
666	        if old_question_ids:
667	            placeholders = ",".join("?" for _ in old_question_ids)
668	            database.execute(
669	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
670	                old_question_ids,
671	            )
672	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
673	        for position, question in enumerate(questions):
674	            question_cursor = database.execute(
675	                "INSERT INTO questions (survey_id, position, type, title, required) "
676	                "VALUES (?, ?, ?, ?, ?)",
677	                (survey_id, position, question["type"], question["title"],
678	                 1 if question["required"] else 0),
679	            )
680	            question_id = question_cursor.lastrowid
681	            for option_position, option in enumerate(question["options"]):
682	                database.execute(
683	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
684	                    (question_id, option_position, option),
685	                )
686	
687	    def replace_survey(survey_id, clean):
688	        """Replace a whole survey atomically; keeps the same id.
689	
690	        Returns False when the survey does not exist (no record is created).
691	        """
692	        row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
693	        if row is None:
694	            return False
695	        try:
696	            database.execute(
697	                "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
698	                (clean["title"], clean["description"], survey_id),
699	            )
700	            write_questions(survey_id, clean["questions"])
701	            database.commit()
702	            return True
703	        except Exception:
704	            database.rollback()
705	            raise
706	
707	    class Handler(BaseHTTPRequestHandler):
708	        def respond(self, status, value, *, html=False, allow=None):
709	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
710	            self.send_response(status)
711	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
712	            self.send_header("Content-Length", str(len(payload)))
713	            if status == 405 and allow is not None:
714	                self.send_header("Allow", ", ".join(allow))
715	            self.end_headers()
716	            self.wfile.write(payload)
717	
718	        def list_surveys(self):
719	            records = [
720	                {"id": row[0], "title": row[1]}
721	                for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
722	            ]
723	            self.respond(200, {RESOURCE: records})
724	
725	        def read_payload(self):
726	            """Read and decode a JSON request body.
727	
728	            Returns (payload, None) or (None, error_message).
729	            """
730	            try:
731	                length = int(self.headers.get("Content-Length") or 0)
732	            except ValueError:
733	                length = -1
734	            if length < 0:
735	                return None, "Content-Length 无效"
736	            if length > MAX_BODY_BYTES:
737	                return None, "请求体过大"
738	            body = self.rfile.read(length) if length else b""
739	            try:
740	                return json.loads(body.decode("utf8")), None
741	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
742	                return None, f"请求体不是合法 JSON：{error}"
743	
744	        def create_survey(self):
745	            payload, error = self.read_payload()
746	            if error is not None:
747	                self.respond(400, {"error": error})
748	                return
749	
750	            clean, error = validate_survey(payload)
751	            if error is not None:
752	                self.respond(400, {"error": error})
753	                return
754	            try:
755	                survey_id = save_survey(clean)
756	            except sqlite3.DatabaseError as error:
757	                self.respond(500, {"error": f"保存失败：{error}"})
758	                return
759	            result = {"id": survey_id, **clean}
760	            self.respond(201, result)
761	
762	        def update_survey(self, survey_id):
763	            payload, read_error = self.read_payload()
764	            if survey_detail(survey_id) is None:
765	                # Editing a missing id is always 404 and must never create one.
766	                self.respond(404, {"error": "not found"})
767	                return
768	            if read_error is not None:
769	                self.respond(400, {"error": read_error})
770	                return
771	
772	            # Full replacement: validate before touching the stored draft so a
773	            # rejected request leaves the old survey exactly as it was.
774	            clean, error = validate_survey(payload)
775	            if error is not None:
776	                self.respond(400, {"error": error})
777	                return
778	            try:
779	                replace_survey(survey_id, clean)
780	            except sqlite3.DatabaseError as error:
781	                self.respond(500, {"error": f"保存失败：{error}"})
782	                return
783	            self.respond(200, {"id": survey_id, **clean})
784	
785	        def route(self):
786	            location = urlsplit(self.path).path
787	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
788	
789	            if location == "/api/surveys":
790	                allowed = ["GET", "POST"]
791	            elif location in ("/", "/health"):
792	                allowed = ["GET"]
793	            elif detail_match:
794	                allowed = ["GET", "PUT"]
795	            else:
796	                self.respond(404, {"error": "not found"})
797	                return
798	
799	            if self.command not in allowed:
800	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
801	                return
802	
803	            if location == "/":
804	                self.respond(200, PAGE, html=True)
805	            elif location == "/health":
806	                self.respond(200, {"status": "ok", "product": PRODUCT})
807	            elif location == "/api/surveys":
808	                if self.command == "POST":
809	                    self.create_survey()
810	                else:
811	                    self.list_surveys()
812	            else:
813	                survey_id = int(detail_match.group(1))
814	                if self.command == "PUT":
815	                    self.update_survey(survey_id)
816	                    return
817	                detail = survey_detail(survey_id)
818	                if detail is None:
819	                    self.respond(404, {"error": "not found"})
820	                else:
821	                    self.respond(200, detail)
822	
823	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
824	
825	    def stop(_signal, _frame):
826	        raise KeyboardInterrupt
827	
828	    signal.signal(signal.SIGTERM, stop)
829	    server = None
830	    try:
831	        server = HTTPServer((args.host, args.port), Handler)
832	        host, port = server.server_address[:2]
833	        address = f"[{host}]" if ":" in host else host
834	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
835	        server.serve_forever()
836	    except KeyboardInterrupt:
837	        pass
838	    finally:
839	        if server is not None:
840	            server.server_close()
841	        database.close()
842	
843	
844	if __name__ == "__main__":
845	    main()
